#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }
    const char *s = argv[1];
    char stack[1024];
    int sp = 0;
    for (size_t i = 0; s[i] != '\0'; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (sp >= (int)sizeof(stack)) { puts("UNBALANCED"); return 0; }
            stack[sp++] = c;
            continue;
        }
        if (c == ')' || c == ']' || c == '}') {
            if (sp == 0) { puts("UNBALANCED"); return 0; }
            char open = stack[--sp];
            if ((open == '(' && c != ')') || (open == '[' && c != ']') || (open == '{' && c != '}')) {
                puts("UNBALANCED"); return 0; }
            continue;
        }
    }
    if (sp == 0) puts("BALANCED"); else puts("UNBALANCED");
    return 0;
}
